const items = $input.all();
const MOCK_UDYAM_REGISTRY = {
  "UDYAM-TEST-001": {
    enterprise_name: "ABC Technologies Pvt Ltd",
    classification: "SMALL",
    major_activity: "SERVICES",
    status: "ACTIVE_VERIFIED",
    state: "Maharashtra",
    district: "Mumbai Suburban",
    nic_codes: ["6201 - Computer programming activities", "6202 - IT Consultancy"],
    date_of_commencement: "2016-08-15",
    msme_benefit_eligible: true
  },
  "UDYAM-MH-12-0012345": {
    enterprise_name: "ABC Technologies Pvt Ltd",
    classification: "SMALL",
    major_activity: "SERVICES",
    status: "ACTIVE_VERIFIED",
    state: "Maharashtra",
    district: "Pune",
    nic_codes: ["6201", "6202"],
    date_of_commencement: "2016-08-15",
    msme_benefit_eligible: true
  },
  "UDYAM-DL-01-0099999": {
    enterprise_name: "Mismatch Enterprises Ltd",
    classification: "MICRO",
    major_activity: "MANUFACTURING",
    status: "ACTIVE_VERIFIED",
    state: "Delhi",
    msme_benefit_eligible: true
  },
  "UDYAM-KA-03-0000000": {
