    classification: "MICRO",
    status: "EXPIRED_SUSPENDED",
    state: "Karnataka",
    msme_benefit_eligible: false
  }
};

let rawInput = {};
try {
  rawInput = $('🔍 Input Validation').first().json || {};
} catch (e) {
  rawInput = {};
}

return items.map(item => {
  const data = item.json;
  const udyam = (data.udyam || (data.evidence && data.evidence.udyam) || (data.evidence && data.evidence.udyam_registration) || rawInput.udyam || (rawInput.raw_input && rawInput.raw_input.udyam) || "").toString().toUpperCase().trim();
  const bidderName = (data.bidder_name || rawInput.bidder_name || (rawInput.raw_input && rawInput.raw_input.bidder_name) || "ABC Technologies Pvt Ltd").toString().trim();
  const registryEntry = MOCK_UDYAM_REGISTRY[udyam] || null;

  return {
    json: {
      ...data,
      bidder_name: bidderName,
      udyam,
      mock_record_found: !!registryEntry,
      mock_udyam_record: registryEntry
    }
  };
});

const items = $input.all();
// Accepts official UDYAM-XX-00-0000000 OR prototype demo UDYAM-TEST-000
const UDYAM_OFFICIAL_REGEX = /^UDYAM-[A-Z]{2}-[0-9]{2}-[0-9]{7}$/;
const UDYAM_DEMO_REGEX = /^UDYAM-TEST-[0-9]{3}$/;

return items.map(item => {
  const data = item.json;
  const udyam = data.udyam || "";
  const formatValid = UDYAM_OFFICIAL_REGEX.test(udyam) || UDYAM_DEMO_REGEX.test(udyam);

  return {
    json: {
      ...data,
      format_valid: formatValid,
      format_type: UDYAM_OFFICIAL_REGEX.test(udyam) ? "OFFICIAL_STATUTORY" : (UDYAM_DEMO_REGEX.test(udyam) ? "PROTOTYPE_DEMO" : "INVALID")
    }
  };
});

const items = $input.all();
return items.map(item => {
  const data = item.json;
  const bidderName = (data.bidder_name || "").toUpperCase().trim();
  const record = data.mock_udyam_record;
  const issues = [];
  let status = "VERIFIED";
  let confidence = 0.97;
  let riskLevel = "LOW";

  if (!data.format_valid) {
    status = "NOT_VERIFIED";
    confidence = 0.95;
    riskLevel = "HIGH";
    issues.push(`Udyam format invalid: '${data.udyam}' does not conform to official Ministry of MSME pattern`);
  } else if (!data.mock_record_found) {
    status = "NOT_VERIFIED";
    confidence = 0.90;
    riskLevel = "HIGH";
    issues.push(`Udyam registration '${data.udyam}' not found in mock MSME registry`);
  } else if (record.status !== "ACTIVE_VERIFIED") {
    status = "NOT_VERIFIED";
    confidence = 0.96;
    riskLevel = "HIGH";
    issues.push(`MSME registration is '${record.status}' for unit ${record.enterprise_name}`);
  } else {
    const regName = record.enterprise_name.toUpperCase().trim();
    const exactMatch = bidderName === regName;
    const partialMatch = bidderName.includes(regName) || regName.includes(bidderName);

    if (!exactMatch && !partialMatch) {
      status = "REVIEW";
      confidence = 0.60;
      riskLevel = "MEDIUM";
      issues.push(`Name consistency mismatch: Bidder name '${data.bidder_name}' differs from MSME registered enterprise '${record.enterprise_name}'`);
    } else {
      status = "VERIFIED";
      confidence = 0.97;
      riskLevel = "LOW";
    }
  }

  return {
    json: {
      ...data,
      name_check_status: status,
      name_check_confidence: confidence,
      name_check_risk: riskLevel,
      name_check_issues: issues
    }
  };
});

const items = $input.all();
return items.map(item => {
  const data = item.json;
  const record = data.mock_udyam_record;

  return {
    json: {
      agent: "UDYAM_AGENT",
      status: data.name_check_status,
      confidence: data.name_check_confidence,
      evidence: {
        udyam_registration: data.udyam,
        enterprise_name: record ? record.enterprise_name : null,
        classification: record ? record.classification : null,
        major_activity: record ? record.major_activity : null,
        status: record ? record.status : "UNREGISTERED",
        state: record ? record.state : null,
        nic_codes: record ? record.nic_codes : [],
        msme_exemption_eligible: record ? record.msme_benefit_eligible : false,
        registry_source: "MOCK_MINISTRY_OF_MSME_PORTAL"
      },
      issues: data.name_check_issues || [],
      risk_level: data.name_check_risk,
      timestamp: new Date().toISOString()
    }
  };
});

const items = $input.all();
return items.map(item => ({
  json: {
    agent: "UDYAM_AGENT",
    status: "REVIEW",
    confidence: 0.0,
    evidence: {
      error: "Udyam verification agent encountered an execution failure",
      fallback_mode: true
    },
    issues: ["Udyam verification agent failed"],
    risk_level: "MEDIUM",
    timestamp: new Date().toISOString()
  }
}));
